customCSS:
.t, .history { color: #7f9f7f; }
.join { color: #7f9f7f; }
.part, .quit { color: #7f9f7f; }
.kick, .error { color: #cc9393; }
.notice { color: #f0dfaf; }
.action { color: #dc8cc3; }
.mode, .nick, .topic, .server { color: #93e0e3; }
.highlight { color: #dcdccc; background-color: #2f2f2f; border-left: 3px solid #dc8cc3; padding-left: 8px; }
.reply { color: #7f9f7f; border-left: 2px solid #8cd0d3; padding-left: 6px; }
.oper { color: #3f3f3f; background-color: #f0dfaf; }
.reactions { color: #8cd0d3; background-color: #4f4f4f; }
.card { background-color: #4f4f4f; border-color: #7f9f7f; }
.card-title { color: #8cd0d3; }
.card-desc { color: #7f9f7f; }
.daychange { color: #7f9f7f; border-color: #4f4f4f; }
